#!/bin/sh
# lint-fmt.sh — run cyrius lint and cyrius fmt --check across every
# hand-edited Cyrius source file in src/ and the audit harness in
# scripts/audit/ (2.9.0). Mandatory pre-release
# step (CLAUDE.md §Gates, §Closeout pass). CI runs the same set;
# either step failing blocks the release.
#
# Skips:
#   - src/grammar_blobs.cyr — auto-generated by
#     scripts/embed-grammars.sh; long string-literal lines are
#     intentional. (CI runs this script.)
#
# `--exit-with-count`: plain `cyrius lint` exits 0 when it only
# WARNS, so through 2.5.0 this script passed with a warning on
# screen — a 147-column line in src/tokenize.cyr shipped in every
# release from 2.4.0 to 2.5.0 under a "lint+fmt exit 0" claim.
# With the flag, the exit code is the warning count, so any
# warning fails the gate.

set -e

cd "$(dirname "$0")/.."

rc=0

for f in src/*.cyr src/grammars/*.cyr scripts/audit/*.cyr; do
    case "$f" in
        src/grammar_blobs.cyr) continue ;;
    esac
    if ! cyrius lint --exit-with-count "$f"; then rc=1; fi
done

if [ "$rc" -ne 0 ]; then
    echo "lint-fmt: lint warnings — fix before release" >&2
    exit "$rc"
fi

for f in src/*.cyr src/grammars/*.cyr scripts/audit/*.cyr; do
    case "$f" in
        src/grammar_blobs.cyr) continue ;;
    esac
    if ! cyrius fmt "$f" --check > /dev/null 2>&1; then
        echo "lint-fmt: $f is not formatted (run 'cyrius fmt $f' to fix)" >&2
        rc=1
    fi
done

if [ "$rc" -eq 0 ]; then
    echo "lint-fmt: OK — src/ and scripts/audit/ lint-clean and formatted"
fi

exit "$rc"
